package com.gameaggregator.deploymentservice.api;import com.gameaggregator.platform.core.common.web.ApiResponse;import com.gameaggregator.deploymentservice.application.DeploymentService;import com.gameaggregator.deploymentservice.domain.*;import jakarta.validation.Valid;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/deployments") public class DeploymentController{final DeploymentService s;public DeploymentController(DeploymentService s){this.s=s;}@PostMapping ApiResponse<Deployment> create(@Valid @RequestBody DeploymentDtos.Create r){return ApiResponse.success(s.create(r));}@GetMapping ApiResponse<List<Deployment>> list(@RequestParam(required=false)UUID releaseId){return ApiResponse.success(s.list(releaseId));}@GetMapping("/{id}")ApiResponse<Deployment> get(@PathVariable UUID id){return ApiResponse.success(s.get(id));}@PostMapping("/{id}/transitions")ApiResponse<Deployment> transition(@PathVariable UUID id,@Valid @RequestBody DeploymentDtos.Transition r){return ApiResponse.success(s.transition(id,r));}@GetMapping("/{id}/events")ApiResponse<List<DeploymentEvent>> events(@PathVariable UUID id){return ApiResponse.success(s.events(id));}}